<section class="page-section"><div class="container narrow"><div class="section-title"><div><p class="eyebrow">LỊCH HOST</p><h1><?= e($listing['title']) ?></h1><p>Chặn hoặc mở một ngày chưa có booking xác nhận.</p></div><a class="btn btn-ghost" href="<?= e(url('/host')) ?>">Quay lại</a></div><div class="surface-card"><form method="post" action="<?= e(url('/api/host/listings/'.$listing['id'].'/availability')) ?>"><div class="form-row align-items-end"><?= csrf_field() ?><div class="form-group col-md-4"><label for="date">Ngày</label><input class="form-control" id="date" type="date" name="date" min="<?= date('Y-m-d') ?>" required></div><div class="form-group col-md-4"><label for="reason">Lý do khi chặn</label><input class="form-control" id="reason" name="reason" placeholder="Bảo trì / việc riêng"></div><div class="form-group col-md-2"><button class="btn btn-outline-danger btn-block" name="open" value="0">Chặn ngày</button></div><div class="form-group col-md-2"><button class="btn btn-primary btn-block" name="open" value="1">Mở ngày</button></div></div></form><h2 class="mt-4">Ngày đã thiết lập</h2><?php if(!$dates): ?><p class="text-muted">Chưa có ngày chặn riêng. Các ngày mặc định đang mở nếu không có booking.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Ngày</th><th>Trạng thái</th><th>Lý do</th><th>Booking</th></tr></thead><tbody><?php foreach($dates as $date): ?><tr><td><?= e($date['stay_date']) ?></td><td><span class="status <?= $date['is_open']?'status-approved':'status-rejected' ?>"><?= $date['is_open']?'Mở':'Đã chặn' ?></span></td><td><?= e($date['block_reason']) ?></td><td><?= $date['booked']?'Đã xác nhận':'—' ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></section>
